func:
// Zweck: msg.sqlite_batch in msg.topic übertragen, damit der SQLite-Node
// das vorbereitete SQL-Statement im Batch-Modus ausführen kann.
//
// Warum dieser Zwischenschritt?
// Die Handler-Functions schreiben ihren SQL-Block nach msg.sqlite_batch.
// Der SQLite-Node im Batch-Modus liest aus msg.topic.
// Dieser Node ist die Brücke zwischen beiden Konventionen.

const batch = typeof msg.sqlite_batch === "string" ? msg.sqlite_batch.trim() : "";

// Leere Batches still verwerfen – passiert z. B. wenn ein Handler
// nichts zu persistieren hat (kein DB-relevanter State-Wechsel).
if (!batch) {
    return null;
}

msg.topic = batch;
return msg;
